<#
.SYNOPSIS
  One-shot, no-admin installer for the IT Atlas Obsidian vault on Windows.

.DESCRIPTION
  Everything installs into your own user profile, so no UAC prompt or admin rights are needed:
    1. Extracts the vault embedded in this script
    2. Installs Obsidian for the current user only (winget --scope user, or the official per-user installer)
    3. Installs the Dataview plugin into the vault
    4. Initialises git in the vault if git is available
    5. Runs the link checker
    6. Registers the vault with Obsidian and opens it
  Claude Code is only installed if you pass -InstallClaudeCode (the official installer is per-user too).
  Nothing is deleted. Existing folders are only replaced with -Force, after a timestamped backup.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File .\setup-it-atlas.ps1
  powershell -ExecutionPolicy Bypass -File .\setup-it-atlas.ps1 -InstallClaudeCode
  powershell -ExecutionPolicy Bypass -File .\setup-it-atlas.ps1 -Dir C:\Users\me\Vaults\IT-Atlas
#>
[CmdletBinding()]
param(
    [string]$Dir = '',
    [switch]$Force,
    [switch]$InstallClaudeCode,
    [switch]$NoObsidian,
    [switch]$NoPlugins,
    [switch]$NoGit,
    [switch]$NoOpen
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }

function Step($m) { Write-Host ""; Write-Host "==> $m" -ForegroundColor Cyan }
function Ok($m)   { Write-Host "   [ok] $m" -ForegroundColor Green }
function Warn($m) { Write-Host "   [!]  $m" -ForegroundColor Yellow }
function Die($m)  { Write-Host "   [x]  $m" -ForegroundColor Red; exit 1 }
function Have($c) { [bool](Get-Command $c -ErrorAction SilentlyContinue) }
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)

# Work folder under LOCALAPPDATA (long path). $env:TEMP can be an 8.3 short path such as
# C:\Users\REX~1.KHA\..., which Remove-Item -LiteralPath in Windows PowerShell 5.1 rejects.
$WorkRoot = Join-Path $env:LOCALAPPDATA 'it-atlas-setup'
if (-not $env:LOCALAPPDATA) { $WorkRoot = Join-Path ([IO.Path]::GetTempPath()) 'it-atlas-setup' }
[IO.Directory]::CreateDirectory($WorkRoot) | Out-Null
function Remove-Safe([string]$Path) {
    try {
        if ([IO.Directory]::Exists($Path)) { [IO.Directory]::Delete($Path, $true) }
        elseif ([IO.File]::Exists($Path)) { [IO.File]::Delete($Path) }
    } catch { }
}
$Stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$PsExe = (Get-Process -Id $PID).Path
$Docs = [Environment]::GetFolderPath('MyDocuments')
if (-not $Docs) { $Docs = Join-Path $HOME 'Documents' }
if (-not $Dir) { $Dir = Join-Path $Docs 'IT-Atlas' }

if (-not $PSCommandPath) { Die "Run this as a saved .ps1 file (it reads its own embedded vault data)." }
$Self = [IO.File]::ReadAllText($PSCommandPath)

function Get-Payload([string]$Tag) {
    $m = [regex]::Match($Self, "(?s)<#${Tag}_BEGIN\s*(.*?)\s*${Tag}_END#>")
    if (-not $m.Success) { return $null }
    return ($m.Groups[1].Value -replace '\s', '')
}

function Install-Vault([string]$Tag, [string]$Inner, [string]$Target) {
    $Target = [IO.Path]::GetFullPath($Target)
    if (Test-Path -LiteralPath $Target) {
        if ($Force) {
            $bak = "$Target.backup-$Stamp"
            Move-Item -LiteralPath $Target -Destination $bak
            Warn "Existing folder moved to $bak"
            $script:RestoreFrom = $bak
        } else {
            Die "$Target already exists. Re-run with -Force to back it up and reinstall, or pass -Dir for another location."
        }
    }
    $b64 = Get-Payload $Tag
    if (-not $b64) { Die "Embedded data '$Tag' not found. Is the script complete?" }
    $tmp = Join-Path $WorkRoot ("vault-" + [guid]::NewGuid().ToString('N'))
    [IO.Directory]::CreateDirectory($tmp) | Out-Null
    try {
        $zip = Join-Path $tmp 'vault.zip'
        [IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String($b64))
        Expand-Archive -LiteralPath $zip -DestinationPath $tmp -Force
        $parent = Split-Path -Parent $Target
        if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
        Move-Item -LiteralPath (Join-Path $tmp $Inner) -Destination $Target
    } finally {
        Remove-Safe $tmp
    }
    $count = @(Get-ChildItem -LiteralPath $Target -Recurse -File -Filter '*.md' | Where-Object { $_.FullName -notmatch '\\\.claude\\' }).Count
    Ok "$count notes extracted to $Target"
    if ($script:RestoreFrom) { Restore-UserContent $script:RestoreFrom $Target; $script:RestoreFrom = $null }
    return $Target
}

function Add-CommunityPlugins([string]$VaultPath, [string[]]$Ids) {
    $cp = Join-Path $VaultPath '.obsidian\community-plugins.json'
    $list = @()
    # Parentheses make Windows PowerShell 5.1 enumerate the JSON array instead of nesting it.
    if (Test-Path -LiteralPath $cp) { try { $list = @((Get-Content -LiteralPath $cp -Raw | ConvertFrom-Json) | ForEach-Object { $_ }) } catch { $list = @() } }
    foreach ($id in $Ids) { if ($id -and ($list -notcontains $id)) { $list += $id } }
    $json = '[' + (($list | ForEach-Object { "`n  `"$_`"" }) -join ',') + "`n]`n"
    [IO.File]::WriteAllText($cp, $json, $Utf8NoBom)
}

# After a -Force reinstall, bring back what the user added to the old copy:
# extra plugins (e.g. Gesture Graph and its downloaded model) and notes they created themselves.
function Restore-UserContent([string]$Old, [string]$New) {
    $oldPlugins = Join-Path $Old '.obsidian\plugins'
    if (Test-Path -LiteralPath $oldPlugins) {
        $ids = @()
        foreach ($d in Get-ChildItem -LiteralPath $oldPlugins -Directory) {
            $dst = Join-Path $New ".obsidian\plugins\$($d.Name)"
            if (-not (Test-Path -LiteralPath $dst)) { Copy-Item -LiteralPath $d.FullName -Destination $dst -Recurse; $ids += $d.Name }
        }
        $oldCp = Join-Path $Old '.obsidian\community-plugins.json'
        if (Test-Path -LiteralPath $oldCp) {
            try { $ids += @((Get-Content -LiteralPath $oldCp -Raw | ConvertFrom-Json) | ForEach-Object { $_ }) } catch { }
        }
        if ($ids.Count) { Add-CommunityPlugins $New $ids; Ok "Kept plugins from the old copy: $((($ids | Select-Object -Unique) -join ', '))" }
    }
    $kept = 0
    $genFile = Join-Path $New '_system\generated-files.txt'
    $generated = @(); if (Test-Path -LiteralPath $genFile) { $generated = [IO.File]::ReadAllLines($genFile) }
    foreach ($f in Get-ChildItem -LiteralPath $Old -Recurse -File -Filter '*.md') {
        $rel = $f.FullName.Substring($Old.Length).TrimStart('\', '/')
        if ($rel -match '^(\.obsidian|\.git|\.trash)[\\/]') { continue }
        $dst = Join-Path $New $rel
        if ($generated -contains ($rel -replace '\\', '/')) { continue }  # a generated note renamed in this version
        if (-not (Test-Path -LiteralPath $dst)) {
            [IO.Directory]::CreateDirectory((Split-Path -Parent $dst)) | Out-Null
            Copy-Item -LiteralPath $f.FullName -Destination $dst
            $kept++
        }
    }
    if ($kept) { Ok "Kept $kept note(s) you created in the old copy" }
    Write-Host "   The old copy is still at $Old. Edits you made to existing notes (such as Field notes) are there."
}

function Find-Obsidian {
    $candidates = @()
    if ($env:LOCALAPPDATA) { $candidates += (Join-Path $env:LOCALAPPDATA 'Programs\Obsidian\Obsidian.exe'), (Join-Path $env:LOCALAPPDATA 'Obsidian\Obsidian.exe') }
    if ($env:ProgramFiles) { $candidates += (Join-Path $env:ProgramFiles 'Obsidian\Obsidian.exe') }
    foreach ($c in $candidates) { if ($c -and (Test-Path -LiteralPath $c)) { return $c } }
    return $null
}

# ------------------------------------------------------------------ 1. vaults
Step "Extracting vaults"
$vaults = @()
$vaults += Install-Vault 'ATLAS' 'IT-Atlas' $Dir

# ------------------------------------------------------------------ 2. Obsidian (per-user)
$obsExe = Find-Obsidian
if (-not $NoObsidian) {
    Step "Checking Obsidian"
    if ($obsExe) {
        Ok "Obsidian already installed ($obsExe)"
    } else {
        if (Have 'winget') {
            Write-Host "   Installing Obsidian for your user only with winget..."
            try {
                & winget install --id Obsidian.Obsidian --exact --scope user --silent --accept-package-agreements --accept-source-agreements | Out-Host
            } catch { Warn "winget failed: $($_.Exception.Message)" }
            $obsExe = Find-Obsidian
        }
        if (-not $obsExe) {
            Write-Host "   Downloading the official per-user installer from GitHub..."
            try {
                $rel = Invoke-RestMethod -Uri 'https://api.github.com/repos/obsidianmd/obsidian-releases/releases/latest' -Headers @{ 'User-Agent' = 'it-atlas-setup' }
                $asset = $rel.assets | Where-Object { $_.name -match '^Obsidian-[\d\.]+\.exe$' } | Select-Object -First 1
                if (-not $asset) { throw "No per-user Windows installer found in release $($rel.tag_name)" }
                $inst = Join-Path $WorkRoot $asset.name
                Invoke-WebRequest -Uri $asset.browser_download_url -OutFile $inst -UseBasicParsing
                $sig = Get-AuthenticodeSignature -FilePath $inst
                if ($sig.Status -ne 'Valid') { throw "Installer signature is not valid ($($sig.Status)); not running it." }
                Ok "Installer signed by: $($sig.SignerCertificate.Subject)"
                Start-Process -FilePath $inst -ArgumentList '/S' -Wait
                Remove-Safe $inst
            } catch { Warn "Download install failed: $($_.Exception.Message)" }
            $obsExe = Find-Obsidian
        }
        if ($obsExe) { Ok "Obsidian installed for your user at $obsExe" }
        else { Warn "Couldn't install Obsidian automatically. Download it from https://obsidian.md/download; the standard installer is per-user and needs no admin rights." }
    }
}

# ------------------------------------------------------------------ 3. Dataview
if (-not $NoPlugins) {
    Step "Installing the Dataview plugin"
    $base = 'https://github.com/blacksmithgu/obsidian-dataview/releases/latest/download'
    foreach ($v in $vaults) {
        $p = Join-Path $v '.obsidian\plugins\dataview'
        New-Item -ItemType Directory -Path $p -Force | Out-Null
        try {
            Invoke-WebRequest -Uri "$base/main.js" -OutFile (Join-Path $p 'main.js') -UseBasicParsing
            Invoke-WebRequest -Uri "$base/manifest.json" -OutFile (Join-Path $p 'manifest.json') -UseBasicParsing
            try { Invoke-WebRequest -Uri "$base/styles.css" -OutFile (Join-Path $p 'styles.css') -UseBasicParsing } catch { }
            Add-CommunityPlugins $v @('dataview')
            $ver = (Get-Content -LiteralPath (Join-Path $p 'manifest.json') -Raw | ConvertFrom-Json).version
            Ok "Dataview $ver installed in $(Split-Path -Leaf $v)"
        } catch {
            Remove-Safe $p
            Warn "Download failed for $(Split-Path -Leaf $v). Install Dataview from Settings > Community plugins instead."
        }
    }
}

# ------------------------------------------------------------------ 4. git
if (-not $NoGit) {
    Step "Setting up git"
    if (Have 'git') {
        $hasId = (& git config user.name) -and (& git config user.email)
        foreach ($v in $vaults) {
            & git -C $v init -q
            & git -C $v add -A
            if ($hasId) { & git -C $v commit -qm "initial import" | Out-Null; Ok "$(Split-Path -Leaf $v): repo initialised with a first commit" }
            else { Warn "$(Split-Path -Leaf $v): repo initialised, nothing committed (git user.name / user.email not set)" }
        }
    } else {
        Warn "git not found; skipping. The vault works without it, you just lose undo history for Claude's edits."
    }
}

# ------------------------------------------------------------------ 5. lint
Step "Checking links"
foreach ($v in $vaults) {
    $lint = Join-Path $v '_system\vault_lint.ps1'
    $out = & $PsExe -NoProfile -ExecutionPolicy Bypass -File $lint 2>&1
    if ($LASTEXITCODE -eq 0) { Ok "$(Split-Path -Leaf $v): $(($out | Select-Object -First 1))" }
    else { Warn "$(Split-Path -Leaf $v) lint reported issues:"; $out | ForEach-Object { Write-Host "     $_" } }
}

# ------------------------------------------------------------------ 6. Claude Code (opt-in)
if ($InstallClaudeCode) {
    Step "Installing Claude Code (per-user)"
    if (Have 'claude') { Ok "Claude Code already installed" }
    else {
        try {
            $ps1 = Join-Path $WorkRoot 'claude-install.ps1'
            Invoke-WebRequest -Uri 'https://claude.ai/install.ps1' -OutFile $ps1 -UseBasicParsing
            & $PsExe -NoProfile -ExecutionPolicy Bypass -File $ps1
            Remove-Safe $ps1
            Ok "Claude Code installed. Open a new terminal so 'claude' is on your PATH."
        } catch { Warn "Claude Code install failed: $($_.Exception.Message)" }
    }
}

# ------------------------------------------------------------------ 7. register + open
if (-not $NoOpen) {
    $obsExe = Find-Obsidian
    if ($obsExe) {
        Step "Opening in Obsidian"
        if (Get-Process -Name 'Obsidian' -ErrorAction SilentlyContinue) {
            Warn "Obsidian is running, so its vault list wasn't touched. Use 'Open folder as vault' and pick $($vaults[0])."
        } else {
            $cfgDir = Join-Path $env:APPDATA 'obsidian'
            $cfgPath = Join-Path $cfgDir 'obsidian.json'
            New-Item -ItemType Directory -Path $cfgDir -Force | Out-Null
            $cfg = $null
            if (Test-Path -LiteralPath $cfgPath) {
                Copy-Item -LiteralPath $cfgPath -Destination "$cfgPath.backup-$Stamp"
                try { $cfg = Get-Content -LiteralPath $cfgPath -Raw | ConvertFrom-Json } catch { $cfg = $null }
            }
            if (-not $cfg) { $cfg = New-Object psobject }
            if (-not $cfg.PSObject.Properties['vaults']) { $cfg | Add-Member -NotePropertyName vaults -NotePropertyValue (New-Object psobject) }
            foreach ($prop in @($cfg.vaults.PSObject.Properties)) {
                if ($prop.Value.PSObject.Properties['open']) { $prop.Value.PSObject.Properties.Remove('open') }
            }
            $now = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
            for ($i = 0; $i -lt $vaults.Count; $i++) {
                $v = $vaults[$i]
                $existing = @($cfg.vaults.PSObject.Properties | Where-Object { $_.Value.path -eq $v }) | Select-Object -First 1
                $entry = New-Object psobject -Property @{ path = $v; ts = $now }
                if ($i -eq 0) { $entry | Add-Member -NotePropertyName open -NotePropertyValue $true }
                if ($existing) { $cfg.vaults.($existing.Name) = $entry }
                else {
                    $id = -join ((1..16) | ForEach-Object { '{0:x}' -f (Get-Random -Maximum 16) })
                    $cfg.vaults | Add-Member -NotePropertyName $id -NotePropertyValue $entry
                }
            }
            [IO.File]::WriteAllText($cfgPath, ($cfg | ConvertTo-Json -Depth 10), $Utf8NoBom)
            Ok "Vault(s) registered with Obsidian"
            Start-Process -FilePath $obsExe
            Ok "Launched Obsidian. Click 'Trust author and enable plugins' when asked, so Dataview turns on."
        }
    }
}

# ------------------------------------------------------------------ done
Remove-Safe $WorkRoot
Step "Done"
foreach ($v in $vaults) { Write-Host "   Vault:  $v" }
Write-Host "   Start:  open 'Start here' or '00 Home\Home', then the graph view."
Write-Host "   Claude: cd `"$($vaults[0])`"; claude"
if (-not (Have 'claude') -and -not $InstallClaudeCode) {
    Write-Host "           Claude Code isn't installed. Re-run with -InstallClaudeCode, or run: winget install Anthropic.ClaudeCode"
}
exit 0

